MOD = 998244353

def count_integers(N, X, A):
    dp = [0] * (X + 1)
    for num in A:
        dp[num] += 1

    for x in range(X):
        if dp[x] > 0:
            dp[2 * x] += dp[x]

    for x in range(X):
        if dp[x] > 0:
            for y in range(x, X + 1):
                dp[y ^ x] += dp[x] * dp[y & ~x]

    return sum(dp[:X + 1]) % MOD

