MOD = 998244353

def solve(N, X, A):
    X_bin = bin(X)[2:]
    X_len = len(X_bin)

    dp = [set() for _ in range(X_len)]
    for num in A:
        dp[0].add(num)

    for i in range(1, X_len):
        new_dp = set()
        for x in dp[i-1]:
            new_dp.add(x << 1)
            for y in dp[i-1]:
                new_dp.add(x ^ y)
        dp[i] = new_dp

    result = 0
    for i in range(X_len):
        for num in dp[i]:
            if num > X:
                continue
            if num.bit_length() <= i + 1:
                result += 1
                result %= MOD

    return result

